// ***************
// Filename: spi_master_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of spi_master: joins the register map
//   spi_master_regs (modport regs) and the logic spi_master (modport core).
//   cfg_* go from the register map to the logic (register values, _wr write
//   pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   spi_master_regs.json: edit the JSON and regenerate.
// Date: 2026-10-20
interface spi_master_regs_if ();
  logic [16-1:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [16-1:0] cfg_div;
  logic cfg_div_wr;
  logic [6-1:0] cfg_word_len;
  logic cfg_word_len_wr;
  logic [32-1:0] sts_status;
  logic [32-1:0] cfg_status;
  logic cfg_status_wr;

  modport regs (output cfg_ctrl, cfg_ctrl_wr, cfg_div, cfg_div_wr, cfg_word_len, cfg_word_len_wr, cfg_status,
    cfg_status_wr, input sts_status);
  modport core (output sts_status, input cfg_ctrl, cfg_ctrl_wr, cfg_div, cfg_div_wr, cfg_word_len,
    cfg_word_len_wr, cfg_status, cfg_status_wr);
  modport monitor (input cfg_ctrl, cfg_ctrl_wr, cfg_div, cfg_div_wr, cfg_word_len, cfg_word_len_wr,
    cfg_status, cfg_status_wr, sts_status);
endinterface
